window.__posterData({"id": "bahram-bader", "name": "Bahram Bader", "folder": "Week3_Poster_Bahram_Bader_AI", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "/* The first step was to ask Claude to refactor the code without changing the functionality of the p5 poster from week 1.  This is the same instruction as the assignment. After I did it Claude only managed to change it from 150 lines to 146 lines on the first attempt. The new code has consts for width and height at the top. It also has it for the framerate and the size of the images. The color arrays for the circles and general color array are now const instead of let. Everything is a const instead of let except img it’s still a let. Const is for unchangeable values. The changes have mostly been organizational, adding functions to things that didn’t have them before. Everything here has been mentioned in class except double array for the text const and I understood everything.  \n\nI will now ask it again to make the code with as few possible lines as possible while maintaining the same functionality. Here is the command: “Rewrite this with as few possible lines as possible while maintaining the same functionality.” It didn’t work the first time so I asked it to try again. It’s now 29 lines of code instead of 150 lines of code. In this one it has the zones of the lights in an const array. It also hovered in an const. I understand what the code the in hovered but don’t understand how it came to the solution for it to work. In the new code framerate is in setup. There is also a .map load image after the image array. MousePressed function is not unusual except for “?” And “:” in the code. It’s also more compressed than the previous code. In the draw function claude makes a for loop that generates the text and the text and the size and the position is now placed in a double array like this array[][]. It now goes through each text in the loop and applies the font, colors, size and position.  \n\n \n\nThe next step was to change 1 element. That is to make the text color gradient instead of flickering between the traffic light colors. This will make it more consistent with the rainbow gradient colored traffic man. This was the command: “Change that the text color is a gradient of red at the top, yellow in the middle and green at the bottom.” My thought was that Claude would have the gradient of red at the top yellow in the middle and green at the bottom for each text. But that wasn’t the case it instead made the top text red the middle text yellow and bottom text green but with a gradient that passes through the whole text instead of the individual texts.  \n\nMy initial plan had it to be red text at the top yellow text at the middle and green text at the bottom. But after looking at rave poster examples it was better to have each text have the gradient. But I didn’t have the technical expertise to execute it.  \n\nI will try again to make each text a gradient instead of a sweeping gradient over all the text. Here is the command: “Can you make each individual text have the gradient instead and not one sweeping gradient.” Now it’s correct but the problem is the red color is to weak and the green is to overpower the rest of the colors. I will try to tell Claude to make it 33% red, 33% yellow and 33% green. Here is the command: “Can you make the gradient 33% red, 33% yellow and 33% green?”. This didn’t look good. I will return to the previous one which looked better. I will try again by asking it to make the red more visible. Here is the command: “can you make the red more visible in the gradient?” This one worked and looked better than the previous two. This is also in line with how I wanted the gradient to look.  \n\nThe final step is to ask Claude to add one additional feature that it thinks is fun. The command for this is the same as the assignment. Claude decided to make the lights blink in order like real traffic lights. This is also an idea I had but I didn’t have the technical skills to make it happen. */\n\nlet img = [], colors = ['#FF0000', '#FFFF00', '#00FF00'], xs = [40, 220, 400];\nconst zones = [[46, 153, 46, 153], [195, 303, 196, 300], [346, 453, 346, 453]];\nconst hovered = () => zones.findIndex(([a, b, c, d]) => mouseX > a && mouseX < b && mouseY > c && mouseY < d);\n\nasync function setup() {\n  createCanvas(600, 800);\n  frameRate(5);\n  img = await Promise.all(['traffic_light_man.png', 'traffic_light_man_walking_left.png', 'traffic_light_man_walking_right.png'].map(f => loadImage(f)));\n}\n\nfunction mousePressed() {\n  let h = hovered(), c = frameCount % 3;\n  if (!mouseIsPressed || h < 0 || img.length < 3) return;\n  if (h == 0) { background(colors[0]); image(img[0], 40, 560, 150, 150); }\n  else {\n    if (h == 2 || c < 2) background(colors[c]);\n    if (c > 0) image(img[c], h == 2 ? random(50, 350) : 220, h == 2 ? random(500, 650) : 560, 150, 150);\n  }\n}\n\nfunction draw() {\n  background('#000000');\n  mousePressed();\n\n  // Traffic light chase: the lit circle (red, then yellow, then green) is bigger and glows, the others are dimmed\n  for (let i = 0; i < 3; ++i) {\n    let on = i == 2 - frameCount % 3, c = color(colors[2 - i]);\n    c.setAlpha(on ? 255 : 70);\n    drawingContext.shadowBlur = on ? 60 : 0;\n    drawingContext.shadowColor = colors[2 - i];\n    fill(c);\n    circle(400 - i * 150, 400 - i * 150, on ? 130 : 100);\n  }\n  drawingContext.shadowBlur = 0;\n\n  // Each text gets its own gradient. Red stays solid for the top 40%, then blends to yellow and green.\n  [['Traffic', 180, 150, 150], ['Light', 320, 290, 120], ['Rave', 470, 420, 55], ['18', 50, 290, 100], ['November', 60, 400, 50], ['2026', 290, 400, 30]]\n    .forEach(([t, x, y, s]) => {\n      let g = drawingContext.createLinearGradient(0, y - s * 0.75, 0, y);\n      [[0, 0], [0.4, 0], [0.65, 1], [1, 2]].forEach(([p, i]) => g.addColorStop(p, colors[i]));\n      drawingContext.fillStyle = g;\n      textFont('OpenSans'); textSize(s); text(t, x, y);\n    });\n\n  let h = hovered();\n  if (h >= 0 && !mouseIsPressed && img.length == 3) image(img[h], xs[h], 560, 150, 150);\n}", "assets": {"traffic_light_man_walking_right.png": {"mime": "image/webp", "b64": ""}, "traffic_light_man.png": {"mime": "image/webp", "b64": ""}, "traffic_light_man_walking_left.png": {"mime": "image/webp", "b64": ""}}});
